PRODUCTS = [
    {"id": 1, "name": "Smartphone", "price": 500, "image": "📱"},
    {"id": 2, "name": "Laptop", "price": 800, "image": "💻"},
    {"id": 3, "name": "Headphones", "price": 200, "image": "🎧"},
]

