    init_session()

    product = next((p for p in PRODUCTS if p["id"] == product_id), None)
    if product:
        cart_item = next(
            (item for item in session["cart"] if item["id"] == product_id), None
        )
        if cart_item:
            cart_item["quantity"] += 1
        else:
            session["cart"].append(
